<script setup lang="ts">
import { onMounted,onBeforeUnmount,getCurrentInstance,ref } from 'vue'
import { getMyAttendance } from '@/services/attendancePersonal'
import { getMyEmployeeStatus } from '@/services/iamAccount'
import { iamMessage } from '@/services/iamAccess'
import type { AttendanceRow } from '@/types/iam'
const rows=ref<AttendanceRow[]>([]),page=ref(1),total=ref(0),from=ref(''),to=ref(''),loading=ref(true),error=ref('')
const viewInstance = import.meta.env.DEV ? getCurrentInstance()?.uid : undefined
let generation=0
const logLabels:Record<string,string>={IN:'签到',OUT:'签退'}, statusLabels:Record<string,string>={Present:'出勤',Absent:'缺勤', 'On Leave':'请假','Half Day':'半天','Work From Home':'居家办公'}
const columns=[{title:'记录类型',key:'source',width:'20%'},{title:'日期',dataIndex:'date',width:'20%'},{title:'打卡时间',dataIndex:'time',width:'25%'},{title:'打卡类型',key:'log_type',width:'15%'},{title:'考勤结果',key:'status',width:'20%'}]
async function load(){const run=++generation;loading.value=true;error.value='';try{const association=await getMyEmployeeStatus();if(run!==generation)return;if(association.status!=='linked'){rows.value=[];total.value=0;error.value=association.status==='conflict'?'员工档案关联存在冲突，请联系负责人核对。':'当前账号尚未关联有效员工档案，请联系负责人完成关联。';return};const result=await getMyAttendance({...(from.value?{date_from:from.value}:{}),...(to.value?{date_to:to.value}:{}),page:page.value,page_size:20});if(run===generation){rows.value=result.rows;total.value=result.total}}catch(e){if(run===generation){rows.value=[];total.value=0;error.value=(e as {code?:string}).code==='FORBIDDEN'?'当前本人考勤访问未获授权，可能已暂停或权限已到期。请联系负责人核对应用权限。':iamMessage(e)}}finally{if(run===generation)loading.value=false}}
const permissionsChanged=()=>{rows.value=[];void load()}
onMounted(()=>{void load();window.addEventListener('hbos:permissions-changed',permissionsChanged)})
onBeforeUnmount(()=>{generation++;window.removeEventListener('hbos:permissions-changed',permissionsChanged)})
</script>
<template><section class="my-attendance" :data-view-instance="viewInstance"><div class="page-heading"><div><h1>我的考勤</h1><p>仅显示当前本人关联员工的考勤。同事记录不会返回。</p></div></div><section class="attendance-panel glass-surface"><div class="attendance-toolbar"><label>开始日期<a-input v-model:value="from" type="date" aria-label="考勤开始日期"/></label><label>结束日期<a-input v-model:value="to" type="date" aria-label="考勤结束日期"/></label><a-button type="primary" :loading="loading" @click="page=1;load()">查询本人考勤</a-button></div><a-alert v-if="error" :message="error" type="warning" show-icon/><a-table :columns="columns" :data-source="rows" row-key="id" table-layout="fixed" :scroll="{x:600}" :loading="loading" :pagination="{current:page,pageSize:20,total,showSizeChanger:false,onChange:(value:number)=>{page=value;load()}}" :locale="{emptyText:error?'当前无法读取本人考勤':'所选日期暂无本人考勤记录'}"><template #bodyCell="{column,record}"><template v-if="column.key === 'source'">{{ record.source === 'Attendance' ? '每日考勤结果' : record.source === 'Employee Checkin' ? '原始打卡' : '待核对的记录类型' }}</template><template v-else-if="column.key === 'log_type'">{{ record.source === 'Attendance' ? '—' : logLabels[record.log_type] || '未识别类型' }}<details v-if="record.log_type"><summary>查看原始值</summary>{{ record.log_type }}</details></template><template v-else-if="column.key === 'status'">{{ record.source === 'Employee Checkin' ? '—' : statusLabels[record.status] || '未识别状态' }}<details v-if="record.status"><summary>查看原始值</summary>{{ record.status }}</details></template></template></a-table><p class="attendance-note">历史记录按原员工主键归属保留。当前未开放部门历史查询或导出。</p></section></section></template>
<style scoped>.my-attendance{font-size:16px;line-height:1.6;min-width:0}.attendance-panel{padding:24px;min-width:0}.attendance-toolbar{display:flex;flex-wrap:wrap;align-items:flex-end;gap:16px;margin-bottom:24px}.attendance-toolbar label{display:grid;gap:8px;font-size:14px}.attendance-note{font-size:14px;color:var(--hbos-text-secondary)}.my-attendance :deep(.ant-table-cell){font-size:16px}.my-attendance :deep(.ant-table-thead .ant-table-cell){font-size:14px}</style>
